-- Named outdoor targets of the original Outland, using 3.3.5 quest texts.
-- Narration describes each NPC; the voice is not the creature speaking.
local entries = {
    {19191, "Араззиус Безжалостный", "Полуостров Адского Пламени", 10136,
        "Араззиус Безжалостный командует наземными силами Пылающего Легиона на Полуострове Адского Пламени. Он служит Владыке Каззаку и готовит наступление на защитников Запределья. Перехваченные планы выдают его роль. Найти этого предводителя демонов можно у прудов Аггонара."},
    {18728, "Владыка судеб Каззак", "Полуостров Адского Пламени", nil,
        "Владыка судеб Каззак — один из полководцев Пылающего Легиона. После возвращения демонов через Тёмный портал он обосновался у Трона Кил'джедена, на севере Полуострова Адского Пламени. Отсюда Каззак руководит силами Легиона в Запределье.",
        "https://warcraft.wiki.gg/wiki/Doom_Lord_Kazzak"},
    {17057, "Свирепая Черноскребка", "Полуостров Адского Пламени", 9466,
        "Свирепая Черноскребка — матриарх камнедеров из пещер Глубокого Разлома. Даже обычные камнедеры опасны, но эта тварь внушает особый страх. За её голову назначена награда, а доказательством победы должны стать её когти. Охота приводит путешественника на самое дно разлома."},
    {18281, "Топехлыст", "Зангартопь", 9895,
        "Топехлыст — огромный болотоброд к югу от Кенарийского оплота. Для друидов его размеры и ярость служат тревожным признаком: природное равновесие Зангартопи нарушено, а некоторые существа становятся всё крупнее и агрессивнее. Встреча с Топехлыстом показывает, как опасны перемены в болотах."},
    {18280, "Спорокрыл", "Зангартопь", 9901,
        "Спорокрыл — гигантский скат из Мёртвой трясины. О нём сообщала ещё первая экспедиция Лиги исследователей, но ей пришлось уйти, не разобравшись с чудовищем. Теперь незавершённую охоту поручают путешественникам. Искать Спорокрыла следует в западной части трясины."},
    {18285, '"Граф" Унгула', "Зангартопь", 9911,
        "Граф Унгула — огромный скат Пустоты из Зангартопи. Его челюсть становится необычным трофеем: по её строению можно судить, что этот зверь уже охотится на живую добычу, а не довольствуется падалью. Для Кенарийской экспедиции это ценный образец, который просят доставить наблюдательнице Лиса'о."},
    {20477, "Жутеклешень", "Зангартопь", 9902,
        "Жутеклешень — гигантский крабстер озера Болотных Огоньков. Наги превратили его охоту в жестокую забаву: они отправляют рабов на острова, когда чудовище выходит за добычей. Убить Жутеклешня просят ради тех, кто стал жертвой этих игр и не может защититься сам."},
    {20555, "Гок", "Острогорье", 10742,
        "Гок — сын Груула и хозяин огров Камнерогов. Его власть угрожает мок'наталам, поэтому союзники путешественника готовят решающее сражение. Чтобы вызвать гронна и получить помощь, нужно добраться до его алтаря у логова Груула. Победа над Гоком должна сломить силу Камнерогов."},
    {20216, "Груллок", "Острогорье", 10995,
        "Груллок, сын Груула, обитает в Окаянной лощине. Его самое дорогое сокровище — драконий череп, которым он хвастается после побед своего отца над чёрными драконами. Мог'дорг просит отнять этот трофей: для его клана борьба с сыновьями Груула становится дорогой к свободе."},
    {20600, "Маггок", "Острогорье", 10996,
        "Маггок — сын Груула, которому поручена охрана восточных горных кряжей Острогорья. Он бродит по Островерхому гребню, пугая и убивая всё живое. С собой гронн постоянно носит сундук с сокровищами. Именно этот сундук Мог'дорг требует принести как доказательство победы над Маггоком."},
    {19554, "Пространствус Всепоглощающий", "Пустоверть", 10437,
        "Пространствус Всепоглощающий пришёл через разрыв Бездны над манагорном Ультрис. Связь с Бездной защищает его, поэтому эфириалы сначала готовят удар по разрыву. Затем капитан Саид и Мстители помогают в сражении с существом, за которым их народ охотился тысячи лет."},
    {20132, "Сокретар", "Пустоверть", 10407,
        "Эредар Сокретар возглавляет силы Пылающего Легиона в Пустоверти. Он отдаёт приказы с отдельного острова, куда допускают лишь доверенных слуг. Алдоры и Провидцы готовят удар по его трону: победа над Сокретаром должна ослабить Легион и раскрыть связи Кель'таса с демонами."},
    {19851, "Негатрон", "Пустоверть", 10248,
        "Негатрон — механический противник на Испытательном полигоне Пустоверти. Здесь доктор Вомиза проверяет свой Утилизатор Х6000 и доверяет путешественнику управление машиной. Сражение с Негатроном становится испытанием нового робота: против железной силы приходится выставить другую машину."},
    {21102, "Уварос", "Долина Призрачной Луны", 10647,
        "Уварос — чудовище скверны, за которым закрепилось прозвище бич Долины Призрачной Луны. Его видели у Руки Гул'дана, в самом сердце долины. За убийство зверя обещана награда, но одних слов охотника недостаточно: доказательством должна стать пламенеющая грива Увароса."},
    {21315, "Руул Светокрад", "Долина Призрачной Луны", 10578,
        "Руул Светокрад перевозит часть Кода Проклятия, которую нельзя позволить доставить Зулухеду. Его путь проходит возле крепости Драконьей Пасти и полей Крыльев Пустоты. Борак поручает перехватить Руула вместе с его транспортом и забрать шифр прежде, чем он попадёт к адресату."},
    {17711, "Судьболом", "Долина Призрачной Луны", nil,
        "Судьболом — огромный сквернобот Пылающего Легиона. Кил'джеден направил эту боевую машину к воротам Чёрного храма, чтобы атаковать твердыню Иллидана. Поэтому великан перед храмом не охраняет его хозяина: он представляет силу Легиона, ведущего собственную войну в Долине Призрачной Луны.",
        "https://warcraft.wiki.gg/wiki/Doomwalker"},
    {18707, "Торгос", "Лес Тероккар", 10035,
        "Торгос — король костеклювов, кружащий над Гнездовьем Рейз на Костяных пустошах. Араккоа отпугивают его пугалом по имени Погибель Торгоса. Чтобы заставить птицу спуститься, охотники используют останки её самки Трашелы. Трофеем этой опасной охоты должно стать перо из хвоста Торгоса."},
    {21838, "Терокк", "Лес Тероккар", 11073,
        "Терокк — легендарный владыка араккоа Скеттиса. Для его возвращения в мир собирают реликвии и трофеи сильнейших обитателей Скеттиса. Хаззик помогает подготовить призыв, а Стражи Небес готовы прикрыть путешественника. Встреча с Терокком завершает опасную цепь охот и древних обрядов."},
    {18290, "Клыкач", "Награнд", 9852,
        "Клыкач — гигантская самка элекка, которую Эрнестуэй называет королевой животного царства Награнда. После охот на талбуков, копытней и ветрухов он предлагает последнее испытание. Клыкач обитает на скале неподалёку от Ошу'гуна, а трофеем должно стать сердце королевы элекков."},
}
for _, entry in ipairs(entries) do
    local id, name, zone, quest, text, source = unpack(entry, 1, 6)
    CatQuest335NpcLore[id] = {
        name = name, title = "История: " .. name, zone = zone,
        text = text, voiceGender = "male",
        source = source or ("https://www.wowhead.com/wotlk/npc=" .. id),
        questSource = quest and ("https://www.wowhead.com/wotlk/ru/quest=" .. quest),
    }
end
